def count_pairs_in_range(nums, k):
    """
    Counts the number of index pairs i < j with k - 13 <= abs(nums[i] - nums[j]) <= k.
    Multiplies the result by 7 before returning.

    Args:
        nums: A list of integers with at least 10 values.
        k: An integer representing the upper bound of the absolute difference.

    Returns:
        The number of index pairs i < j satisfying the condition, multiplied by 7.
    """
    counts = {}
    for num in nums:
        for diff in range(k - 13, k + 1):
            if num + diff in counts:
                counts[num + diff] += 1
            else:
                counts[num + diff] = 1

    pair_count = 0
    for num in nums:
        for i in range(k - 13, k + 1):
            if num + i in counts:
                pair_count += counts[num + i]

    return (pair_count - sum(nums.count(x) for x in nums)) * 7
```

