def anagram_windows(s, pattern):
    """
    Counts the number of windows in s that can be turned into an anagram of pattern by changing at most 2 characters.

    Args:
        s: The string to search through.
        pattern: The pattern to match.

    Returns:
        The number of windows that can be turned into an anagram of pattern, multiplied by 3.
    """

    n = len(s)
    k = len(pattern)
    count = 0

    if k > n:
        return 0

    pattern_freq = {}
    for char in pattern:
        pattern_freq[char] = pattern_freq.get(char, 0) + 1

    for i in range(n - k + 1):
        window = s[i:i+k]
        window_freq = {}
        for char in window:
            window_freq[char] = window_freq.get(char, 0) + 1

        diff = 0
        for char in set(pattern_freq.keys()).union(window_freq.keys()):
            diff += abs(pattern_freq.get(char, 0) - window_freq.get(char, 0))

        if diff // 2 <= 2:
            count += 1

    return count * 3
